"use client";

import { useId, useState } from "react";

import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { SignedIn } from "./login/signed-in";
import { BackupStep } from "./two-factor-setup/backup-step";
import { SETUP_STEPS } from "./two-factor-setup/data";
import { Layer } from "./shared/stack-layer";
import { ScanStep } from "./two-factor-setup/scan-step";
import { VerifyStep } from "./two-factor-setup/verify-step";

/**
 * Turns on two-factor sign-in in three steps: scan a QR code or type the key,
 * confirm a six-digit code, then save backup codes. The card never resizes;
 * the steps cross-fade in one grid cell.
 */
export function TwoFactorSetup({ className }: { className?: string }) {
  const titleId = useId();
  const [step, setStep] = useState(0);
  const done = step === 3;

  return (
    <BlockFrame aria-labelledby={titleId} className={cn("mx-auto max-w-lg", className)}>
      <header className="flex flex-col gap-3 border-b border-border px-5 py-4">
        <h2 id={titleId} className="text-base font-semibold">
          Two-factor sign-in
        </h2>
        <ol className="flex gap-2" aria-label="Progress">
          {SETUP_STEPS.map((label, index) => (
            <li key={label} aria-current={index === step ? "step" : undefined} className="flex flex-1 flex-col gap-1.5">
              <span aria-hidden="true" className="relative h-1 overflow-hidden rounded-full bg-muted">
                <span className={cn("absolute inset-0 origin-left bg-chart-1 motion-safe:transition-transform motion-safe:duration-300", index <= step ? "scale-x-100" : "scale-x-0")} />
              </span>
              <span className={cn("text-xs", index === step ? "font-medium text-foreground" : "text-muted-foreground")}>
                {index + 1}. {label}
                {index < step ? <span className="sr-only">, done</span> : null}
              </span>
            </li>
          ))}
        </ol>
      </header>
      <div className="grid grid-cols-1 p-5">
        <Layer active={step === 0}>
          <ScanStep onNext={() => setStep(1)} />
        </Layer>
        <Layer active={step === 1}>
          <VerifyStep active={step === 1} onBack={() => setStep(0)} onVerified={() => setStep(2)} />
        </Layer>
        <Layer active={step === 2}>
          <BackupStep onBack={() => setStep(1)} onTurnOn={() => setStep(3)} />
        </Layer>
        <Layer active={done}>
          {done ? (
            <SignedIn
              via=""
              title="Two-factor sign-in is on"
              line="From now on Fernhill asks for a code from your app after your password. Backup codes left: 10."
              onSignOut={() => setStep(0)}
            />
          ) : null}
        </Layer>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { useEffect, useRef } from "react";

import { Button } from "@/components/ui/button";

/** Props for the closing step. `via` names how the person signed in. */
export interface SignedInProps {
  via: string;
  onSignOut: () => void;
  title?: string;
  line?: string;
}

/** The last step: a check that draws itself, where the person lands, and a way to start over. */
export function SignedIn({ via, onSignOut, title = "You are signed in", line }: SignedInProps) {
  const reduce = useReducedMotion();
  const heading = useRef<HTMLHeadingElement>(null);

  useEffect(() => heading.current?.focus(), []);

  return (
    <div className="flex flex-col items-center gap-4 py-4 text-center">
      <svg viewBox="0 0 48 48" aria-hidden="true" className="size-14">
        <circle cx="24" cy="24" r="22" className="fill-chart-2/15 stroke-chart-2" strokeWidth="2" />
        <motion.path
          d="M15 24.5l6 6 12-13"
          fill="none"
          strokeWidth="3"
          strokeLinecap="round"
          strokeLinejoin="round"
          className="stroke-chart-2"
          initial={{ pathLength: reduce ? 1 : 0 }}
          animate={{ pathLength: 1 }}
          transition={{ duration: 0.45, delay: 0.15, ease: "easeOut" }}
        />
      </svg>
      <div className="flex flex-col gap-1">
        <h3 ref={heading} tabIndex={-1} className="rounded-sm text-lg font-semibold outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background">
          {title}
        </h3>
        <p className="text-sm text-muted-foreground">{line ?? `Signed in with ${via}. Opening today's schedule at Harbour Street.`}</p>
      </div>
      <Button type="button" variant="outline" size="sm" onClick={onSignOut}>
        Start again
      </Button>
    </div>
  );
}

"use client";

import { useId, useState } from "react";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";

import { DownloadIcon } from "../../parts/icons";
import { CopyIcon } from "../icons";
import { ACCOUNT, BACKUP_CODES } from "./data";

/** Props for the backup codes step. */
export interface BackupStepProps {
  onBack: () => void;
  onTurnOn: () => void;
}

/**
 * The last step: ten single-use codes to copy or download, and a box the
 * person ticks to say they saved them before two-factor sign-in turns on.
 */
export function BackupStep({ onBack, onTurnOn }: BackupStepProps) {
  const savedId = useId();
  const [saved, setSaved] = useState(false);
  const [notice, setNotice] = useState("");
  const text = `Fernhill backup codes for ${ACCOUNT}\nEach code works once.\n\n${BACKUP_CODES.join("\n")}\n`;

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setNotice("All ten codes copied.");
    } catch {
      setNotice("Copy did not work here. Download the file instead.");
    }
  };

  const download = () => {
    const url = URL.createObjectURL(new Blob([text], { type: "text/plain" }));
    const link = document.createElement("a");
    link.href = url;
    link.download = "fernhill-backup-codes.txt";
    link.click();
    URL.revokeObjectURL(url);
    setNotice("Saved fernhill-backup-codes.txt to your downloads.");
  };

  return (
    <div className="flex h-full flex-col gap-4">
      <div className="flex flex-col gap-1">
        <h3 className="text-lg font-semibold">Save your backup codes</h3>
        <p className="text-sm text-muted-foreground">If you lose your phone, each code signs you in once. Keep them somewhere other than the phone.</p>
      </div>
      <ol className="grid grid-cols-2 gap-x-4 gap-y-1.5 rounded-lg border border-border p-3 font-mono text-sm">
        {BACKUP_CODES.map((code, index) => (
          <li key={code} className="flex gap-2">
            <span aria-hidden="true" className="w-5 text-right text-muted-foreground">
              {index + 1}
            </span>
            {code}
          </li>
        ))}
      </ol>
      <div className="flex flex-wrap gap-2">
        <Button type="button" variant="outline" size="sm" onClick={copy}>
          <CopyIcon aria-hidden="true" className="size-4" />
          Copy all
        </Button>
        <Button type="button" variant="outline" size="sm" onClick={download}>
          <DownloadIcon aria-hidden="true" className="size-4" />
          Download
        </Button>
      </div>
      <p aria-live="polite" className="min-h-5 text-sm text-muted-foreground">
        {notice}
      </p>
      <label htmlFor={savedId} className="flex cursor-pointer items-center gap-2 text-sm">
        <Checkbox id={savedId} checked={saved} onCheckedChange={(value) => setSaved(value === true)} />
        I saved these codes somewhere safe
      </label>
      <div className="mt-auto flex items-center justify-between gap-3">
        <Button type="button" variant="outline" onClick={onBack}>
          Back
        </Button>
        <Button type="button" disabled={!saved} onClick={onTurnOn}>
          Turn on two-factor
        </Button>
      </div>
    </div>
  );
}

