import { motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";

/** One step's layer. Every layer shares the same grid cell, so the card keeps the size of the tallest. */
export function Layer({ active, children }: { active: boolean; children: ReactNode }) {
  const reduce = useReducedMotion();
  return (
    <motion.div
      aria-hidden={!active}
      inert={!active}
      initial={false}
      animate={active ? { opacity: 1, y: 0, visibility: "visible" } : { opacity: 0, y: reduce ? 0 : 8, transitionEnd: { visibility: "hidden" } }}
      transition={{ duration: 0.2, ease: "easeOut", delay: active ? 0.08 : 0 }}
      className="col-start-1 row-start-1 min-w-0"
    >
      {children}
    </motion.div>
  );
}

"use client";

import { useState } from "react";

import { Button } from "@/components/ui/button";

import { CheckIcon } from "../../parts/icons";
import { CopyIcon, PhoneIcon } from "../icons";
import { ACCOUNT, OTP_URI, SECRET } from "./data";
import { QrCode } from "./qr-code";

const APP_KINDS = ["An authenticator app on your phone", "A password manager that keeps codes", "A desktop app for time-based codes"];

/** The first step: a QR code to scan, the kinds of app that read it, and the key to type by hand. */
export function ScanStep({ onNext }: { onNext: () => void }) {
  const [copied, setCopied] = useState(false);
  const grouped = SECRET.match(/.{1,4}/g)?.join(" ") ?? SECRET;

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(SECRET);
      setCopied(true);
    } catch {
      setCopied(false);
    }
  };

  return (
    <div className="flex flex-col gap-5">
      <div className="flex flex-col gap-1">
        <h3 className="text-lg font-semibold">Scan this code</h3>
        <p className="text-sm text-muted-foreground">Open an app that makes time-based codes and add a new account with your camera.</p>
      </div>
      <div className="flex flex-col items-center gap-5 @md:flex-row @md:items-start">
        <QrCode value={OTP_URI} label={`QR code that adds Fernhill for ${ACCOUNT} to an authenticator app`} className="size-40 shrink-0 border border-border" />
        <ul className="flex flex-col gap-2.5 text-sm">
          {APP_KINDS.map((kind) => (
            <li key={kind} className="flex items-start gap-2">
              <PhoneIcon aria-hidden="true" className="mt-0.5 size-4 shrink-0 text-chart-1" />
              {kind}
            </li>
          ))}
        </ul>
      </div>
      <div className="flex flex-col gap-2 rounded-lg border border-border p-3">
        <p className="text-sm text-muted-foreground">Cannot scan? Type this key into the app instead.</p>
        <div className="flex items-center justify-between gap-3">
          <code className="font-mono text-sm font-semibold break-all">{grouped}</code>
          <Button type="button" variant="outline" size="sm" onClick={copy} aria-label={copied ? "Key copied" : "Copy the key"}>
            {copied ? <CheckIcon aria-hidden="true" className="size-4" /> : <CopyIcon aria-hidden="true" className="size-4" />}
            {copied ? "Copied" : "Copy"}
          </Button>
        </div>
        <p aria-live="polite" className="sr-only">
          {copied ? "Key copied." : ""}
        </p>
      </div>
      <Button type="button" onClick={onNext}>
        I added it, continue
      </Button>
    </div>
  );
}

"use client";

import { useMemo } from "react";

import { cn } from "@/lib/utils";

import { encodeQr } from "./qr";

/**
 * A scannable QR code for `value`, drawn dark on a light tile in light and
 * dark themes, because some phone cameras cannot read a light-on-dark code.
 */
export function QrCode({ value, label, className }: { value: string; label: string; className?: string }) {
  const modules = useMemo(() => encodeQr(value), [value]);
  const size = modules.length;
  const quiet = 3;
  const view = size + quiet * 2;

  const path = modules
    .flatMap((row, y) => row.map((dark, x) => (dark ? `M${x + quiet} ${y + quiet}h1v1h-1z` : "")))
    .join("");

  return (
    // The light colour scheme pins Canvas to white and CanvasText to black, so
    // the code stays dark on a light tile in both themes.
    <svg role="img" aria-label={label} viewBox={`0 0 ${view} ${view}`} className={cn("scheme-light rounded-lg", className)}>
      <rect width={view} height={view} fill="Canvas" />
      <path d={path} fill="CanvasText" />
    </svg>
  );
}

// A small QR encoder: byte mode, error correction level L, versions 1 to 5
// (one block each), mask 0. Enough for an authenticator link of up to 106 bytes.

// Total codewords and error correction codewords per version, level L.
const CAPACITY: [number, number][] = [
  [26, 7],
  [44, 10],
  [70, 15],
  [100, 20],
  [134, 26],
];

/** Multiplies two numbers in GF(256) with the QR polynomial. */
function gfMultiply(a: number, b: number) {
  let result = 0;
  for (let bit = 7; bit >= 0; bit--) {
    result = (result << 1) ^ ((result >>> 7) * 0x11d);
    result ^= ((b >>> bit) & 1) * a;
  }
  return result & 0xff;
}

/** The Reed-Solomon error correction bytes for one block of data. */
function correction(data: number[], degree: number) {
  const divisor = Array.from<unknown, number>({ length: degree }, (_, index) => (index === degree - 1 ? 1 : 0));
  let root = 1;
  for (let i = 0; i < degree; i++) {
    for (let j = 0; j < degree; j++) {
      divisor[j] = gfMultiply(divisor[j]!, root) ^ (divisor[j + 1] ?? 0);
    }
    root = gfMultiply(root, 0x02);
  }
  const remainder = new Array<number>(degree).fill(0);
  for (const byte of data) {
    const factor = byte ^ remainder.shift()!;
    remainder.push(0);
    divisor.forEach((coefficient, index) => {
      remainder[index]! ^= gfMultiply(coefficient, factor);
    });
  }
  return remainder;
}

/** The data codewords: mode, length, the bytes, a terminator and padding. */
function dataCodewords(bytes: number[], capacity: number) {
  const bits: number[] = [];
  const push = (value: number, length: number) => {
    for (let bit = length - 1; bit >= 0; bit--) bits.push((value >>> bit) & 1);
  };
  push(0b0100, 4);
  push(bytes.length, 8);
  for (const byte of bytes) push(byte, 8);
  push(0, Math.min(4, capacity * 8 - bits.length));
  while (bits.length % 8) bits.push(0);
  const words: number[] = [];
  for (let index = 0; index < bits.length; index += 8) words.push(parseInt(bits.slice(index, index + 8).join(""), 2));
  for (let pad = 0xec; words.length < capacity; pad ^= 0xec ^ 0x11) words.push(pad);
  return words;
}

/**
 * Encodes text as a QR symbol and returns its modules, row by row: true is a
 * dark module. Throws when the text is longer than version 5 holds.
 */
export function encodeQr(text: string): boolean[][] {
  const bytes = [...new TextEncoder().encode(text)];
  const versionIndex = CAPACITY.findIndex(([total, ecc]) => total - ecc - 2 >= bytes.length);
  if (versionIndex < 0) throw new Error("Text is too long for this encoder.");
  const version = versionIndex + 1;
  const [total, ecc] = CAPACITY[versionIndex]!;
  const size = version * 4 + 17;

  const modules = Array.from({ length: size }, () => new Array<boolean>(size).fill(false));
  const reserved = Array.from({ length: size }, () => new Array<boolean>(size).fill(false));
  const set = (x: number, y: number, dark: boolean) => {
    modules[y]![x] = dark;
    reserved[y]![x] = true;
  };

  for (let index = 0; index < size; index++) {
    set(6, index, index % 2 === 0);
    set(index, 6, index % 2 === 0);
  }
  const finder = (cx: number, cy: number) => {
    for (let dy = -4; dy <= 4; dy++) {
      for (let dx = -4; dx <= 4; dx++) {
        const x = cx + dx;
        const y = cy + dy;
        const ring = Math.max(Math.abs(dx), Math.abs(dy));
        if (x >= 0 && x < size && y >= 0 && y < size) set(x, y, ring !== 2 && ring !== 4);
      }
    }
  };
  finder(3, 3);
  finder(size - 4, 3);
  finder(3, size - 4);
  if (version > 1) {
    const at = size - 7;
    for (let dy = -2; dy <= 2; dy++) {
      for (let dx = -2; dx <= 2; dx++) set(at + dx, at + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
    }
  }

  // Format bits for level L (01) and mask 0, with their BCH check bits.
  const format = (() => {
    const data = 0b01 << 3;
    let remainder = data;
    for (let index = 0; index < 10; index++) remainder = (remainder << 1) ^ ((remainder >>> 9) * 0x537);
    return ((data << 10) | remainder) ^ 0x5412;
  })();
  const bit = (index: number) => ((format >>> index) & 1) === 1;
  for (let index = 0; index <= 5; index++) set(8, index, bit(index));
  set(8, 7, bit(6));
  set(8, 8, bit(7));
  set(7, 8, bit(8));
  for (let index = 9; index < 15; index++) set(14 - index, 8, bit(index));
  for (let index = 0; index < 8; index++) set(size - 1 - index, 8, bit(index));
  for (let index = 8; index < 15; index++) set(8, size - 15 + index, bit(index));
  set(8, size - 8, true);

  const data = dataCodewords(bytes, total - ecc);
  const codewords = [...data, ...correction(data, ecc)];
  let cursor = 0;
  for (let right = size - 1; right >= 1; right -= 2) {
    if (right === 6) right = 5;
    for (let vertical = 0; vertical < size; vertical++) {
      for (let column = 0; column < 2; column++) {
        const x = right - column;
        const upward = ((right + 1) & 2) === 0;
        const y = upward ? size - 1 - vertical : vertical;
        if (reserved[y]![x]) continue;
        const dark = cursor < codewords.length * 8 && ((codewords[cursor >>> 3]! >>> (7 - (cursor & 7))) & 1) === 1;
        cursor++;
        modules[y]![x] = dark !== ((x + y) % 2 === 0);
      }
    }
  }
  return modules;
}

"use client";

import { useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";

import { LoaderIcon } from "../icons";
import { CodeSlots } from "../shared/code-slots";
import { useTimers } from "../shared/use-timers";
import { SAMPLE_CODE } from "./data";

/** Props for the confirm step. `active` is false while the step is hidden. */
export interface VerifyStepProps {
  active: boolean;
  onBack: () => void;
  onVerified: () => void;
}

/** The second step: type the six digits the app shows, to prove the app is set up. */
export function VerifyStep({ active, onBack, onVerified }: VerifyStepProps) {
  const errorId = useId();
  const { later } = useTimers();
  const [code, setCode] = useState("");
  const [checking, setChecking] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const form = useRef<HTMLFormElement>(null);

  // The layer turns visible a moment after it activates, so focus waits for it.
  useEffect(() => {
    if (!active) return;
    const timer = setTimeout(() => form.current?.querySelector("input")?.focus(), 120);
    return () => clearTimeout(timer);
  }, [active]);

  const verify = (value: string) => {
    setChecking(true);
    setError(null);
    later(() => {
      setChecking(false);
      if (value === SAMPLE_CODE) {
        setCode("");
        onVerified();
      } else {
        setError("That code did not match. Codes change every 30 seconds, so use the newest one.");
      }
    }, 600);
  };

  return (
    <form
      ref={form}
      className="flex h-full flex-col gap-5"
      onSubmit={(event) => {
        event.preventDefault();
        if (code.length === 6) verify(code);
        else setError("Enter all six digits.");
      }}
    >
      <div className="flex flex-col gap-1">
        <h3 className="text-lg font-semibold">Enter the code from the app</h3>
        <p className="text-sm text-muted-foreground">The app now shows a six-digit code for Fernhill. Type it here before it changes.</p>
      </div>
      {active ? (
        <CodeSlots
          label="Code from your authenticator"
          value={code}
          onChange={(value) => {
            setCode(value);
            if (error) setError(null);
          }}
          onComplete={verify}
          invalid={error !== null}
          disabled={checking}
          describedBy={errorId}
        />
      ) : (
        <div className="h-12" />
      )}
      <p id={errorId} aria-live="polite" className="min-h-10 text-sm text-destructive">
        {error}
      </p>
      <p className="text-sm text-muted-foreground">Sample code for this demo: {SAMPLE_CODE.slice(0, 3)} {SAMPLE_CODE.slice(3)}</p>
      <div className="mt-auto flex items-center justify-between gap-3">
        <Button type="button" variant="outline" onClick={onBack} disabled={checking}>
          Back
        </Button>
        <Button type="submit" disabled={checking}>
          {checking ? <LoaderIcon aria-hidden="true" className="size-4 motion-safe:animate-spin" /> : null}
          {checking ? "Checking" : "Confirm code"}
        </Button>
      </div>
    </form>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type ClipboardEvent, type KeyboardEvent, useRef } from "react";

import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

/** Props for six one-digit slots that together hold a sign-in code. */
export interface CodeSlotsProps {
  /** The digits typed so far, up to six. */
  value: string;
  onChange: (value: string) => void;
  /** Runs when the sixth digit lands, with the whole code. */
  onComplete: (code: string) => void;
  /** Names the group for screen readers, such as "Code from your authenticator". */
  label: string;
  /** Marks every slot as wrong, after a code was refused. */
  invalid?: boolean;
  disabled?: boolean;
  /** The id of the line that explains an error, read with the group. */
  describedBy?: string;
  autoFocus?: boolean;
}

const LENGTH = 6;

/**
 * Six slots for a one-time code. Typing a digit moves to the next slot and
 * the sixth submits. Backspace clears a slot or steps back; arrows, Home and
 * End move between slots; pasting fills all six.
 */
export function CodeSlots({
  value,
  onChange,
  onComplete,
  label,
  invalid,
  disabled,
  describedBy,
  autoFocus,
}: CodeSlotsProps) {
  const reduce = useReducedMotion();
  const slots = useRef<(HTMLInputElement | null)[]>([]);
  const digits = Array.from(
    { length: LENGTH },
    (_, index) => value[index] ?? "",
  );

  const focusSlot = (index: number) =>
    slots.current[Math.max(0, Math.min(LENGTH - 1, index))]?.focus();

  const commit = (next: string) => {
    // While a code is being checked the slots keep focus but take no input.
    if (disabled) return;
    const clean = next.replace(/\D/g, "").slice(0, LENGTH);
    onChange(clean);
    if (clean.length === LENGTH) onComplete(clean);
  };

  const writeAt = (index: number, digit: string) => {
    const chars = digits.slice();
    chars[index] = digit;
    // Slots before the typed one cannot stay empty, so the code is always read from the left.
    const filled = chars.join("");
    commit(filled);
    focusSlot(Math.min(filled.length, LENGTH - 1));
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>, index: number) => {
    const moves = new Map([
      ["ArrowLeft", index - 1],
      ["ArrowRight", index + 1],
      ["Home", 0],
      ["End", LENGTH - 1],
    ]);
    const target = moves.get(event.key);
    if (target !== undefined) {
      event.preventDefault();
      focusSlot(target);
      return;
    }
    if (event.key === "Backspace") {
      event.preventDefault();
      if (digits[index]) {
        commit(value.slice(0, index) + value.slice(index + 1));
      } else if (index > 0) {
        commit(value.slice(0, index - 1) + value.slice(index));
        focusSlot(index - 1);
      }
      return;
    }
    if (/^\d$/.test(event.key)) {
      event.preventDefault();
      writeAt(Math.min(index, value.length), event.key);
    }
  };

  const onPaste = (event: ClipboardEvent<HTMLInputElement>) => {
    event.preventDefault();
    const pasted = event.clipboardData
      .getData("text")
      .replace(/\D/g, "")
      .slice(0, LENGTH);
    if (!pasted) return;
    commit(pasted);
    focusSlot(Math.min(pasted.length, LENGTH - 1));
  };

  return (
    <div
      role="group"
      aria-label={label}
      aria-describedby={describedBy}
      className="flex items-center gap-2"
    >
      {digits.map((digit, index) => (
        <span
          key={index}
          // The typed digit and its selection stay transparent, so only the animated digit above it shows.
          className={cn(
            "relative flex-1 text-transparent caret-transparent selection:bg-transparent selection:text-transparent",
            index === 3 && "ml-2",
            disabled && "opacity-60",
          )}
        >
          <Input
            ref={(element) => {
              slots.current[index] = element;
            }}
            type="text"
            inputMode="numeric"
            autoComplete={index === 0 ? "one-time-code" : "off"}
            aria-label={`Digit ${index + 1} of ${LENGTH}`}
            aria-invalid={invalid || undefined}
            autoFocus={autoFocus && index === 0}
            readOnly={disabled}
            aria-busy={disabled || undefined}
            value={digit}
            onChange={(event) => {
              const typed = event.target.value.replace(/\D/g, "");
              if (typed.length > 1) commit(typed);
              else if (typed) writeAt(Math.min(index, value.length), typed);
            }}
            onKeyDown={(event) => onKeyDown(event, index)}
            onPaste={onPaste}
            onFocus={(event) => event.target.select()}
            className="h-12 text-center"
          />
          <span
            aria-hidden="true"
            className="pointer-events-none absolute inset-0 flex items-center justify-center text-lg font-semibold text-foreground tabular-nums"
          >
            <AnimatePresence initial={false}>
              {digit ? (
                <motion.span
                  key={digit}
                  initial={reduce ? { opacity: 0 } : { opacity: 0, y: 6 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, position: "absolute" }}
                  transition={{ duration: 0.16, ease: "easeOut" }}
                >
                  {digit}
                </motion.span>
              ) : null}
            </AnimatePresence>
          </span>
        </span>
      ))}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef } from "react";

/**
 * Schedules the simulated waits a demo needs, such as a server reply. Every
 * pending timer is cleared when the block unmounts or `clear` runs.
 */
export function useTimers() {
  const pending = useRef(new Set<ReturnType<typeof setTimeout>>());

  const clear = useCallback(() => {
    for (const timer of pending.current) clearTimeout(timer);
    pending.current.clear();
  }, []);

  const later = useCallback((run: () => void, ms: number) => {
    const timer = setTimeout(() => {
      pending.current.delete(timer);
      run();
    }, ms);
    pending.current.add(timer);
    return timer;
  }, []);

  useEffect(() => clear, [clear]);

  return { later, clear };
}
